spec.setup_code:
var TXT='#04204B',SEC='#3D5F91',GUIDE='#8098BC',BLUE='#0B4FC0',WARM='#B4552F',VIO='#6A47C2';
var T=15;
var ctx=null;
function sm(x){x=x<0?0:(x>1?1:x);return x*x*(3-2*x);}
var seed=11;
function rnd(){seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296;}
var words=['a','red','fox','in','snow'];
var pref=[1,1,2,2,2,3,4,4];
var S=[],A=[],C=[],maxJ=0,maxC=0,q,k,i,j;
for(q=0;q<13;q++){S[q]=[];for(k=0;k<13;k++){
 var s=rnd()*1.4;var qi=q>=5,ki=k>=5;
 if(qi&&ki)s+=2.2*Math.exp(-Math.pow(q-k,2)/2);
 else if(qi&&!ki)s+=2.0*(pref[q-5]===k?1:0);
 else if(!qi&&ki)s+=1.6*(pref[k-5]===q?1:0);
 else s+=2.2*(q===k?1:0)+0.6*(Math.abs(q-k)===1?1:0);
 S[q][k]=s;}}
for(q=0;q<13;q++){A[q]=[];var z=0;for(k=0;k<13;k++){A[q][k]=Math.exp(S[q][k]);z+=A[q][k];}
 for(k=0;k<13;k++){A[q][k]/=z;if(A[q][k]>maxJ)maxJ=A[q][k];}}
for(i=0;i<8;i++){C[i]=[];var z2=0;for(j=0;j<5;j++){C[i][j]=Math.exp(S[5+i][j]);z2+=C[i][j];}
 for(j=0;j<5;j++){C[i][j]/=z2;if(C[i][j]>maxC)maxC=C[i][j];}}
function rr(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.arcTo(x+w,y,x+w,y+r,r);ctx.lineTo(x+w,y+h-r);ctx.arcTo(x+w,y+h,x+w-r,y+h,r);ctx.lineTo(x+r,y+h);ctx.arcTo(x,y+h,x,y+h-r,r);ctx.lineTo(x,y+r);ctx.arcTo(x,y,x+r,y,r);ctx.closePath();}
function arrow(x1,y1,x2,y2,col,al,lw,head){
 if(al<0.01)return;
 ctx.globalAlpha=al;ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;
 ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();
 if(head){var a=Math.atan2(y2-y1,x2-x1);ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-6*Math.cos(a-0.4),y2-6*Math.sin(a-0.4));ctx.lineTo(x2-6*Math.cos(a+0.4),y2-6*Math.sin(a+0.4));ctx.closePath();ctx.fill();}
 ctx.globalAlpha=1;}
function dot(x1,y1,x2,y2,u,col,al){if(al<0.01)return;u=u-Math.floor(u);ctx.globalAlpha=al;ctx.fillStyle=col;ctx.beginPath();ctx.arc(x1+(x2-x1)*u,y1+(y2-y1)*u,2.4,0,6.283);ctx.fill();ctx.globalAlpha=1;}
function txt(s,x,y,col,al,align,maxW){
 if(al<0.01)return;
 ctx.font='12px sans-serif';
 if(maxW&&ctx.measureText(s).width>maxW)ctx.font='11px sans-serif';
 ctx.globalAlpha=al;ctx.fillStyle=col;ctx.textAlign=align||'center';ctx.textBaseline='alphabetic';
 ctx.fillText(s,x,y);ctx.globalAlpha=1;}
function halo(s,x,y,al){
 if(al<0.01)return;
 ctx.font='11px sans-serif';ctx.textAlign='center';ctx.globalAlpha=al;
 ctx.lineWidth=3;ctx.strokeStyle='#ffffff';ctx.strokeText(s,x,y);
 ctx.fillStyle=TXT;ctx.fillText(s,x,y);ctx.globalAlpha=1;}
var blocks=[
 {r0:5,r1:13,c0:0,c1:5,s:5.3,a:'image',b:'→ text'},
 {r0:5,r1:13,c0:5,c1:13,s:6.3,a:'image',b:'→ image'},
 {r0:0,r1:5,c0:5,c1:13,s:7.3,a:'text',b:'→ image'},
 {r0:0,r1:5,c0:0,c1:5,s:8.3,a:'text',b:'→ text'}];
return {draw:function(c,W,H,time,dt){
 ctx=c;
 ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);
 var t=time%T;
 var narrow=W<600;
 var g=1-sm((t-14.2)/0.8);
 var ca=sm(t/0.8)*(1-sm((t-4.8)/0.8));
 var cm=sm(t/0.8)*(1-sm((t-4.4)/0.7));
 var jm=sm((t-4.8)/0.7)*(1-sm((t-9.8)/0.7));
 var dim=1-0.65*sm((t-10)/0.8);
 var ja1=sm((t-5)/0.8)*g*dim;
 var ja2=sm((t-7)/1.0)*g*dim;
 var wob=sm((t-7.2)/1.0)*g;
 var cap1=sm(t/0.6)*(1-sm((t-4.6)/0.6));
 var cap2=sm((t-4.9)/0.6)*(1-sm((t-9.7)/0.6));
 var cap3=sm((t-10)/0.6)*(1-sm((t-14.3)/0.6));
 var x0=16,x1,yT,yI,labT,labI,R,bh;
 if(narrow){x1=W-16;yT=66;yI=120;labT=44;labI=148;bh=24;R={x:12,y:160,w:W-24,h:H-160-30};}
 else{x1=Math.floor(W*0.5)-8;yT=H*0.25;yI=H*0.64;labT=yT-34;labI=yI+38;bh=30;R={x:W*0.52,y:48,w:W*0.48-14,h:H-48-34};}
 var availW=x1-x0,pI=availW/8,pT=availW/5;
 var bwI=Math.min(46,pI-5),bwT=Math.min(60,pT-6);
 var txx=[],tyy=[];
 for(j=0;j<5;j++){txx[j]=x0+pT*(j+0.5)+Math.sin(time*6+j*1.3)*2.2*wob;tyy[j]=yT+Math.cos(time*5+j)*1.5*wob;}
 var capY=22,cw0=W-16;
 txt('Cross-attention (SD 1, SDXL): text stays frozen',W/2,capY,TXT,cap1,'center',cw0);
 txt('Joint attention (SD3, FLUX): one 13-token sequence',W/2,capY,TXT,cap2,'center',cw0);
 txt('Separate weights per stream, shared attention',W/2,capY,TXT,cap3,'center',cw0);
 txt('1/3 · Q from image · K, V from text · text unchanged',W/2,H-10,SEC,cap1,'center',cw0);
 txt('2/3 · Q, K, V from all 13 tokens · text updates too',W/2,H-10,SEC,cap2,'center',cw0);
 txt('3/3 · own weights per stream · one shared softmax',W/2,H-10,SEC,cap3,'center',cw0);
 txt('text tokens (5)',x0,labT,SEC,1,'left');
 txt('image tokens (8)',x0,labI,SEC,1,'left');
 if(ja1>0.01){
  ctx.globalAlpha=ja1;ctx.strokeStyle=GUIDE;ctx.lineWidth=1;ctx.setLineDash([4,4]);
  rr(x0-6,labT-14,availW+12,yI+bh/2+5-(labT-14),8);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;
  txt('concat [text ; image] = 13 tokens',x1,labT,SEC,ja1,'right');}
 if(ca>0.01){
  var lx=x1-48;ctx.globalAlpha=ca;ctx.strokeStyle=WARM;ctx.fillStyle=WARM;ctx.lineWidth=1.6;
  ctx.beginPath();ctx.arc(lx,labT-8,3.6,Math.PI,0);ctx.stroke();
  ctx.fillRect(lx-5.5,labT-8,11,8);ctx.globalAlpha=1;
  txt('frozen',lx+9,labT,WARM,ca,'left');}
 var yIt=yI-bh/2,yTb=yT+bh/2;
 if(ca>0.01||ja1>0.01||ja2>0.01){
  for(i=0;i<8;i++){for(j=0;j<5;j++){
   var xi=x0+pI*(i+0.5);
   var vc=C[i][j]/maxC,vj=A[5+i][j]/maxJ,vt=A[j][5+i]/maxJ;
   if(ca>0.01){
    arrow(xi,yIt,x0+pT*(j+0.5),yTb,BLUE,ca*(0.05+0.7*vc),1.2,vc>0.4);
    if(vc>0.45)dot(xi,yIt,x0+pT*(j+0.5),yTb,time*0.5+i*0.13+j*0.07,BLUE,ca);}
   if(ja1>0.01){
    arrow(xi-3,yIt,txx[j]-3,tyy[j]+bh/2,BLUE,ja1*(0.05+0.7*vj),1.2,vj>0.4);
    if(vj>0.45)dot(xi-3,yIt,txx[j]-3,tyy[j]+bh/2,time*0.5+i*0.13+j*0.07,BLUE,ja1);}
   if(ja2>0.01){
    arrow(txx[j]+3,tyy[j]+bh/2,xi+3,yIt,WARM,ja2*(0.05+0.7*vt),1.2,vt>0.4);
    if(vt>0.45)dot(txx[j]+3,tyy[j]+bh/2,xi+3,yIt,time*0.5+i*0.11+j*0.09+0.4,WARM,ja2);}
  }}}
 for(j=0;j<5;j++){
  var br=wob*(0.5+0.5*Math.sin(time*4-j));
  var tx=txx[j]-bwT/2,ty=tyy[j]-bh/2;
  if(br>0.05){ctx.globalAlpha=br*0.5;ctx.strokeStyle=WARM;ctx.lineWidth=3;rr(tx-2,ty-2,bwT+4,bh+4,8);ctx.stroke();ctx.globalAlpha=1;}
  ctx.globalAlpha=0.14+0.4*br;ctx.fillStyle=WARM;rr(tx,ty,bwT,bh,6);ctx.fill();ctx.globalAlpha=1;
  ctx.strokeStyle=WARM;ctx.lineWidth=1.5;rr(tx,ty,bwT,bh,6);ctx.stroke();
  txt(words[j],txx[j],tyy[j]+4,TXT,1,'center');}
 for(i=0;i<8;i++){
  var xc=x0+pI*(i+0.5);
  var pl=0.5+0.5*Math.sin(time*4-i*0.7);
  ctx.globalAlpha=0.14+0.18*pl*Math.max(ca,ja1);ctx.fillStyle=BLUE;rr(xc-bwI/2,yI-bh/2,bwI,bh,6);ctx.fill();ctx.globalAlpha=1;
  ctx.strokeStyle=BLUE;ctx.lineWidth=1.5;rr(xc-bwI/2,yI-bh/2,bwI,bh,6);ctx.stroke();
  txt('z'+(i+1),xc,yI+4,TXT,1,'center');}
 var mt=R.y+40;
 if(cm>0.01){
  var ch=Math.min((R.h-40-18)/8,36),cw=Math.min((R.w-40)/5,ch*1.7);
  var mx=R.x+(R.w-5*cw)/2+6,my=mt;
  txt('A = softmax(QK^T/√d)  (8×5)',R.x+R.w/2,R.y+10,TXT,cm,'center',R.w);
  for(i=0;i<8;i++){for(j=0;j<5;j++){
   var rev=sm((t-0.3)*1.0-(i+j)*0.08);
   ctx.globalAlpha=cm*rev*(0.06+0.94*C[i][j]/maxC);ctx.fillStyle=BLUE;ctx.fillRect(mx+j*cw,my+i*ch,cw,ch);}}
  ctx.globalAlpha=cm;ctx.strokeStyle=GUIDE;ctx.lineWidth=1;ctx.strokeRect(mx,my,5*cw,8*ch);
  ctx.fillStyle=BLUE;for(i=0;i<8;i++)ctx.fillRect(mx-8,my+i*ch+1,5,ch-2);
  ctx.fillStyle=WARM;for(j=0;j<5;j++)ctx.fillRect(mx+j*cw+1,my-8,cw-2,5);
  ctx.globalAlpha=1;
  for(j=0;j<5;j++)txt(words[j],mx+(j+0.5)*cw,my-12,SEC,cm,'center');
  txt('rows: image queries · cols: text keys',R.x+R.w/2,my+8*ch+14,SEC,cm,'center',R.w);}
 if(jm>0.01){
  var ms=Math.min(R.w-30,R.h-40-18),cl=ms/13;
  var jx=R.x+(R.w-ms)/2+6,jy=mt;
  txt('A = softmax(QK^T/√d)  (13×13)',R.x+R.w/2,R.y+10,TXT,jm,'center',R.w);
  ctx.globalAlpha=jm;ctx.strokeStyle=GUIDE;ctx.lineWidth=1;ctx.strokeRect(jx,jy,ms,ms);
  for(k=0;k<13;k++){ctx.fillStyle=k<5?WARM:BLUE;ctx.fillRect(jx-8,jy+k*cl+1,5,cl-2);ctx.fillRect(jx+k*cl+1,jy-8,cl-2,5);}
  ctx.globalAlpha=1;
  var bi,r,cc;
  for(bi=0;bi<4;bi++){
   var b=blocks[bi],p=sm((t-b.s)/1.0),nr=b.r1-b.r0,nc=b.c1-b.c0;
   if(p<=0)continue;
   ctx.fillStyle=b.r0<5?WARM:BLUE;
   for(r=b.r0;r<b.r1;r++){for(cc=b.c0;cc<b.c1;cc++){
    var rv=p*1.6-((r-b.r0)+(cc-b.c0))/(nr+nc)*0.6;rv=rv<0?0:(rv>1?1:rv);
    ctx.globalAlpha=jm*rv*(0.06+0.94*A[r][cc]/maxJ);
    ctx.fillRect(jx+cc*cl,jy+r*cl,cl,cl);}}
   ctx.globalAlpha=jm*p;ctx.strokeStyle=GUIDE;ctx.lineWidth=1;
   ctx.strokeRect(jx+b.c0*cl,jy+b.r0*cl,nc*cl,nr*cl);ctx.globalAlpha=1;
   var bcx=jx+(b.c0+nc/2)*cl,bcy=jy+(b.r0+nr/2)*cl;
   halo(b.a,bcx,bcy-3,jm*p);halo(b.b,bcx,bcy+10,jm*p);}
  txt('rows = queries · cols = keys',R.x+R.w/2,jy+ms+14,SEC,jm,'center',R.w);}
 if(t>10){
  var aB=sm((t-10)/0.6)*g,aC=sm((t-10.8)/0.6)*g,aA=sm((t-11.6)/0.6)*g;
  var hh=R.h-42,c0=R.y+26,yt=c0+hh*0.25,yi=c0+hh*0.75;
  var bw=Math.max(66,R.w*0.24),bx=R.x+4,bhh=34;
  var chx=R.x+R.w*0.47,chw=26,chh=16;
  var ax=R.x+R.w*0.74,aw=R.x+R.w-4-ax;
  txt('Q, K, V projections per stream',R.x+R.w/2,R.y+10,TXT,aB,'center',R.w);
  var s2,kk;
  for(s2=0;s2<2;s2++){
   var yc=s2?yi:yt,col=s2?BLUE:WARM;
   ctx.globalAlpha=aB*0.14;ctx.fillStyle=col;rr(bx,yc-bhh/2,bw,bhh,6);ctx.fill();
   ctx.globalAlpha=aB;ctx.strokeStyle=col;ctx.lineWidth=1.6;rr(bx,yc-bhh/2,bw,bhh,6);ctx.stroke();ctx.globalAlpha=1;
   txt(s2?'W_image':'W_text',bx+bw/2,yc+4,TXT,aB,'center');
   txt(s2?'from image tokens z':'from text tokens c',bx,yc-bhh/2-5,SEC,aB,'left');
   var names=['Q','K','V'];
   for(kk=0;kk<3;kk++){
    var cy=yc+(kk-1)*20;
    arrow(bx+bw,yc,chx,cy,col,aC*0.6,1.2,false);
    arrow(chx+chw,cy,ax,cy,col,aC*0.6,1.2,true);
    dot(bx+bw,yc,chx,cy,time*0.7+kk*0.3+s2*0.5,col,aC);
    dot(chx+chw,cy,ax,cy,time*0.7+kk*0.3+s2*0.5+0.5,col,aC);
    ctx.globalAlpha=aC*0.14;ctx.fillStyle=col;rr(chx,cy-chh/2,chw,chh,4);ctx.fill();
    ctx.globalAlpha=aC;ctx.strokeStyle=col;ctx.lineWidth=1.2;rr(chx,cy-chh/2,chw,chh,4);ctx.stroke();ctx.globalAlpha=1;
    ctx.font='bold 11px sans-serif';ctx.globalAlpha=aC;ctx.fillStyle=TXT;ctx.textAlign='center';ctx.fillText(names[kk],chx+chw/2,cy+4);ctx.globalAlpha=1;}}
  var ay0=yt-30,ay1=yi+30;
  ctx.globalAlpha=aA*0.1;ctx.fillStyle=VIO;rr(ax,ay0,aw,ay1-ay0,8);ctx.fill();
  ctx.globalAlpha=aA;ctx.strokeStyle=VIO;ctx.lineWidth=1.6;rr(ax,ay0,aw,ay1-ay0,8);ctx.stroke();ctx.globalAlpha=1;
  var amid=(ay0+ay1)/2;
  txt('shared',ax+aw/2,amid-8,TXT,aA,'center');
  txt('attention',ax+aw/2,amid+7,TXT,aA,'center');
  txt('13 tokens',ax+aw/2,amid+22,SEC,aA,'center');
  txt('outputs are split back per stream',R.x+R.w/2,R.y+R.h-4,SEC,aA,'center',R.w);}
}};
